package main

import (
	"fmt"
	"log"
	"os"
)

// errLogger writes diagnostics in the classic "date time file:line: msg"
// layout.  The location label is supplied explicitly by the caller so the
// output does not depend on the physical layout of this source tree.
var errLogger = log.New(os.Stderr, "", log.Ldate|log.Ltime|log.Lmicroseconds)

// fatalAt prints the operands (joined like fmt.Sprint) prefixed with the
// given location label and terminates the process with status 1.
func fatalAt(loc string, v ...interface{}) {
	errLogger.Output(2, loc+": "+fmt.Sprint(v...))
	os.Exit(1)
}

// fatallnAt is the fmt.Sprintln flavoured variant of fatalAt.
func fatallnAt(loc string, v ...interface{}) {
	errLogger.Output(2, loc+": "+fmt.Sprintln(v...))
	os.Exit(1)
}
EOF
cat > color.go <<'EOF'
package main

import "strings"

const (
	colorGray    = "90"
	colorGreen   = "92"
	colorMagenta = "95"
	colorCyan    = "96"
	colorReset   = "\033[0m"
)

// Color wraps str into an ANSI colour escape sequence.
func Color(str, code string) string {
	return "\033[" + code + "m" + str + colorReset
}

func colorStart(code string) string {
	return "\033[" + code + "m"
}

// ColorfulJson adds colours to a JSON document: object keys are shown in
// magenta, values in cyan.  The scanner is deliberately lightweight; it
// walks the text byte by byte and tracks only a little state.
func ColorfulJson(str string) string {
	var buf strings.Builder
	buf.Grow(len(str) + len(str)/2)

	magenta := colorStart(colorMagenta)
	cyan := colorStart(colorCyan)

	color := ""     // colour to emit in front of the next token
	open := true    // a colour span is open and awaits a reset
	inString := false

	for i := 0; i < len(str); i++ {
		c := str[i]
		if inString {
			if c == '"' && (i == 0 || str[i-1] != '\\') {
				buf.WriteString(colorReset)
				buf.WriteByte('"')
				inString = false
				color = ""
				open = false
			} else {
				buf.WriteByte(c)
			}
			continue
		}
		switch c {
		case '"':
			if color != "" {
				buf.WriteByte('"')
				buf.WriteString(color)
				inString = true
			} else {
				buf.WriteString(colorReset)
				buf.WriteByte('"')
				open = false
			}
		case '{':
			buf.WriteByte(c)
			color = magenta
		case '}':
			buf.WriteByte(c)
			color = ""
			open = true
		case ':':
			if open {
				buf.WriteString(colorReset)
			}
			buf.WriteByte(c)
			color = cyan
			open = false
		case ',':
			if open {
				buf.WriteString(colorReset)
			}
			buf.WriteByte(c)
			color = magenta
			open = false
		case ' ', '\n', '\r', '[', ']':
			buf.WriteByte(c)
		default:
			if color != "" {
				buf.WriteString(color)
				color = ""
				open = true
			}
			buf.WriteByte(c)
		}
	}
	return buf.String()
}
EOF
echo done"}

