	return &Request{
		url:    rawurl,
		req:    req,
		params: map[string]string{},
		files:  map[string]string{},
		resp:   &http.Response{},
		proxy:  http.ProxyFromEnvironment,
	}, nil
}

// Header sets a request header.
func (r *Request) Header(key, value string) *Request {
	r.req.Header.Set(key, value)
	return r
}

// SetHost overrides the Host header.
func (r *Request) SetHost(host string) *Request {
	r.req.Host = host
	return r
}

// Param registers a form/query parameter.
func (r *Request) Param(key, value string) *Request {
	r.params[key] = value
	return r
}

// PostFile registers a file to be uploaded as multipart form data.
func (r *Request) PostFile(formname, filename string) *Request {
	r.files[formname] = filename
	return r
}

// Body sets a raw request body.
func (r *Request) Body(data interface{}) *Request {
	switch t := data.(type) {
	case string:
		bf := bytes.NewBufferString(t)
		r.req.Body = ioutil.NopCloser(bf)
		r.req.ContentLength = int64(len(t))
	case []byte:
		bf := bytes.NewBuffer(t)
		r.req.Body = ioutil.NopCloser(bf)
		r.req.ContentLength = int64(len(t))
	}
	return r
}

// JsonBody encodes data as JSON and uses it as the request body.
func (r *Request) JsonBody(data interface{}) (*Request, error) {
	if r.req.Body == nil && data != nil {
		buf := bytes.NewBuffer(nil)
		enc := json.NewEncoder(buf)
		if err := enc.Encode(data); err != nil {
			return r, err
		}
		r.req.Body = ioutil.NopCloser(buf)
		r.req.ContentLength = int64(buf.Len())
		r.req.Header.Set("Content-Type", "application/json")
	}
	return r, nil
}

// SetBasicAuth configures HTTP basic authentication.
func (r *Request) SetBasicAuth(username, password string) *Request {
	r.req.SetBasicAuth(username, password)
	return r
}

// SetTLSClientConfig sets the TLS settings used for https requests.
func (r *Request) SetTLSClientConfig(config *tls.Config) *Request {
	r.tlsConfig = config
	return r
}

// SetProxy routes the request through the given proxy.
func (r *Request) SetProxy(proxy func(*http.Request) (*url.URL, error)) *Request {
	r.proxy = proxy
	return r
}

// GetRequest returns the underlying http.Request.
func (r *Request) GetRequest() *http.Request {
	return r.req
}

// DumpRequest returns the wire form of the request captured right before it
// was sent.
func (r *Request) DumpRequest() []byte {
	return r.dump
}

func (r *Request) paramBody() string {
	if len(r.params) == 0 {
		return ""
	}
	var buf bytes.Buffer
	for k, v := range r.params {
		buf.WriteString(url.QueryEscape(k))
		buf.WriteByte('=')
		buf.WriteString(url.QueryEscape(v))
		buf.WriteByte('&')
	}
	s := buf.String()
	return s[:len(s)-1]
}

func (r *Request) buildURL(paramBody string) {
	// GET requests carry their parameters in the query string.
	if r.req.Method == "GET" && len(paramBody) > 0 {
		if strings.Contains(r.url, "?") {
			r.url += "&" + paramBody
		} else {
			r.url = r.url + "?" + paramBody
		}
		return
	}

	// POST/PUT/PATCH requests without an explicit body get a form body.
	if (r.req.Method == "POST" || r.req.Method == "PUT" || r.req.Method == "PATCH") && r.req.Body == nil {
		if len(r.files) > 0 {
			pr, pw := io.Pipe()
			bodyWriter := multipart.NewWriter(pw)
			go func() {
				for formname, filename := range r.files {
					fileWriter, err := bodyWriter.CreateFormFile(formname, filename)
					if err != nil {
						fatalAt("httplib.go:324", err)
					}
					fh, err := os.Open(filename)
					if err != nil {
						fatalAt("httplib.go:328", err)
					}
					_, err = io.Copy(fileWriter, fh)
					fh.Close()
					if err != nil {
						fatalAt("httplib.go:334", err)
					}
				}
				for k, v := range r.params {
					bodyWriter.WriteField(k, v)
				}
				bodyWriter.Close()
				pw.Close()
			}()
			r.Header("Content-Type", bodyWriter.FormDataContentType())
			r.req.Body = ioutil.NopCloser(pr)
			return
		}
		if len(paramBody) > 0 {
			r.Header("Content-Type", "application/x-www-form-urlencoded")
			r.Body(paramBody)
		}
	}
}

// MakeRequest finalises the URL/body of the request and returns it.  Every
// call re-applies the parameters, mirroring the behaviour of the builder it
// replaces.
func (r *Request) MakeRequest() (*http.Request, error) {
	r.buildURL(r.paramBody())
	u, err := url.Parse(r.url)
	if err != nil {
		return nil, err
	}
	r.req.URL = u
	return r.req, nil
}

func timeoutDialer(cTimeout, rwTimeout time.Duration) func(string, string) (net.Conn, error) {
	return func(netw, addr string) (net.Conn, error) {
		conn, err := net.DialTimeout(netw, addr, cTimeout)
		if err != nil {
			return nil, err
		}
		err = conn.SetDeadline(time.Now().Add(rwTimeout))
		return conn, err
	}
}

// Transport builds the transport used to perform the request.
func (r *Request) Transport() *http.Transport {
	return &http.Transport{
		TLSClientConfig: r.tlsConfig,
		Proxy:           r.proxy,
		Dial:            timeoutDialer(connectTimeout, readWriteTimeout),
	}
}

func (r *Request) getResponse() (*http.Response, error) {
	if r.resp.StatusCode != 0 {
		return r.resp, nil
	}
	req, err := r.MakeRequest()
	if err != nil {
		return nil, err
	}
	client := &http.Client{Transport: r.Transport()}

	dump, err := httputil.DumpRequest(req, true)
	if err != nil {
		println(err.Error())
	}
	r.dump = dump

	resp, err := client.Do(req)
	if err != nil {
		return nil, err
	}
	r.resp = resp
	return resp, nil
}

// Response performs the request (once) and returns the response.
func (r *Request) Response() (*http.Response, error) {
	return r.getResponse()
}

// Bytes returns the (gzip-decoded if needed) response body.
func (r *Request) Bytes() ([]byte, error) {
	if r.body != nil {
		return r.body, nil
	}
	resp, err := r.getResponse()
	if err != nil {
		return nil, err
	}
	if resp.Body == nil {
		return nil, nil
	}
	defer resp.Body.Close()
	if resp.Header.Get("Content-Encoding") == "gzip" {
		reader, err := gzip.NewReader(resp.Body)
		if err != nil {
			return nil, err
		}
		r.body, err = ioutil.ReadAll(reader)
	} else {
		r.body, err = ioutil.ReadAll(resp.Body)
	}
	return r.body, err
}
