package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"regexp"
	"strings"
)

var jsonContentType = regexp.MustCompile(`application/.*json`)

func getHTTP(method string, rawurl string, args []string) *Request {
	r, err := NewRequest(rawurl, method)
	if err != nil {
		fatalAt("bat.go:158", err)
	}
	r.Header("User-Agent", "bat/"+version)
	r.Header("Accept-Encoding", "gzip, deflate")
	if isjson {
		r.Header("Accept", "application/json")
	} else if form || method == "GET" {
		r.Header("Accept", "*/*")
	} else {
		r.Header("Accept", "application/json")
	}

	jsonmap := map[string]interface{}{}
	for _, arg := range args {
		switch {
		case strings.Contains(arg, ":"):
			// header
			kv := strings.SplitN(arg, ":", 2)
			if kv[0] == "Host" {
				r.SetHost(kv[1])
			}
			r.Header(kv[0], kv[1])
		case strings.Contains(arg, "="):
			// query string or post data
			kv := strings.SplitN(arg, "=", 2)
			if method == "GET" || form {
				r.Param(kv[0], kv[1])
			} else {
				jsonmap[kv[0]] = kv[1]
			}
		case strings.Contains(arg, "@"):
			// file upload
			kv := strings.SplitN(arg, "@", 2)
			if isjson {
				// JSON requests cannot carry files; the item is ignored.
				continue
			}
			if !form {
				fatalAt("http.go:52", "file upload only support in forms style: -f=true")
			}
			r.PostFile(kv[0], kv[1])
		}
	}

	if !form && method != "GET" && len(jsonmap) > 0 {
		r.Header("Content-Type", "application/json")
		buf := bytes.NewBuffer(nil)
		enc := json.NewEncoder(buf)
		if err := enc.Encode(jsonmap); err != nil {
			fatalAt("http.go:66", err)
		}
		r.Body(buf.Bytes())
	}
	return r
}

func wantSection(section string) bool {
	return strings.Contains(printV, "A") || strings.Contains(printV, section)
}

// printRequest prints the request headers (H) and body (B) in colour.
func printRequest(r *Request) {
	dump := string(r.DumpRequest())
	headerPart, bodyPart := dump, ""
	if idx := strings.Index(dump, "\r\n\r\n"); idx >= 0 {
		headerPart = dump[:idx+2]
		bodyPart = dump[idx+4:]
	}

	if wantSection("H") {
		lines := strings.Split(headerPart, "\n")
		for i, line := range lines {
			if line == "" {
				continue
			}
			if i == 0 {
				parts := strings.Split(line, " ")
				if len(parts) >= 3 {
