		r.Header("Accept", "*/*")
	} else {
		r.Header("Accept", "application/json")
	}

	jsonmap := map[string]interface{}{}
	for _, arg := range args {
		switch {
		case strings.Contains(arg, ":"):
			// header
			kv := strings.SplitN(arg, ":", 2)
			if kv[0] == "Host" {
				r.SetHost(kv[1])
			}
			r.Header(kv[0], kv[1])
