cat > progress.go <<'EOF'
package main

import (
	"fmt"
	"io"
	"math"
	"strings"
	"sync"
	"time"
)

const (
	progressWidth       = 123
	progressRefreshRate = 200 * time.Millisecond
)

const (
	unitKB = 1024
	unitMB = unitKB * 1024
	unitGB = unitMB * 1024
	unitTB = unitGB * 1024
)

func formatBytes(i int64) string {
	switch {
	case i >= unitTB:
		return fmt.Sprintf("%.2f TB", float64(i)/unitTB)
	case i >= unitGB:
		return fmt.Sprintf("%.2f GB", float64(i)/unitGB)
	case i >= unitMB:
		return fmt.Sprintf("%.2f MB", float64(i)/unitMB)
	case i >= unitKB:
		return fmt.Sprintf("%.2f KB", float64(i)/unitKB)
	default:
		return fmt.Sprintf("%d B", i)
	}
}

// ProgressBar renders a textual download progress indicator.
type ProgressBar struct {
	total     int64
	current   int64
	startTime time.Time

	mu        sync.Mutex
	lastValue int64
	finished  bool
	done      chan struct{}
}

// NewProgressBar creates a bar for total bytes (<= 0 means unknown).
func NewProgressBar(total int64) *ProgressBar {
	return &ProgressBar{total: total, done: make(chan struct{})}
}

// Start begins periodic refreshing of the bar.
func (p *ProgressBar) Start() *ProgressBar {
	p.startTime = time.Now()
	go p.refresher()
	return p
}

func (p *ProgressBar) refresher() {
	for {
		select {
		case <-p.done:
			return
		default:
			p.Update()
			time.Sleep(progressRefreshRate)
		}
	}
}

// Add increases the current value.
func (p *ProgressBar) Add(n int) {
	p.mu.Lock()
	p.current += int64(n)
	p.mu.Unlock()
}

// Update redraws the bar when the value changed since the last draw.
func (p *ProgressBar) Update() {
	p.mu.Lock()
	defer p.mu.Unlock()
	if p.finished {
		return
	}
	if p.current != p.lastValue {
		p.write(p.current)
		p.lastValue = p.current
	}
}

// Finish draws the final state of the bar.
func (p *ProgressBar) Finish() {
	p.mu.Lock()
	defer p.mu.Unlock()
	if p.finished {
		return
	}
	p.finished = true
	close(p.done)
	p.write(p.current)
}

func (p *ProgressBar) write(current int64) {
	width := progressWidth
	var percentBox, countersBox, timeLeftBox, speedBox, barBox, end string

	if p.total > 0 {
		percent := float64(current) / (float64(p.total) / float64(100))
		percentBox = fmt.Sprintf(" %.2f %% ", percent)
		countersBox = fmt.Sprintf("%s / %s ", formatBytes(current), formatBytes(p.total))
	} else {
		countersBox = formatBytes(current) + " "
	}

	fromStart := time.Now().Sub(p.startTime)
	if p.finished {
		left := (fromStart / time.Second) * time.Second
		timeLeftBox = left.String()
	} else if p.total > 0 && current > 0 {
		perEntry := fromStart / time.Duration(current)
		left := time.Duration(p.total-current) * perEntry
		left = (left / time.Second) * time.Second
		timeLeftBox = left.String()
	}

	if current > 0 {
		speed := float64(current) / (float64(fromStart) / float64(time.Second))
		speedBox = formatBytes(int64(speed)) + "/s "
	}

	if p.total > 0 {
		size := width - len(countersBox+"["+"]"+percentBox+timeLeftBox+speedBox)
		if size > 0 {
			curCount := int(math.Ceil((float64(current) / float64(p.total)) * float64(size)))
			emptCount := size - curCount
			barBox = "["
			if emptCount < 0 {
				emptCount = 0
			}
			if curCount > size {
				curCount = size
			}
			if emptCount <= 0 {
				barBox += strings.Repeat("=", curCount)
			} else if curCount > 0 {
				barBox += strings.Repeat("=", curCount-1) + ">"
			}
			barBox += strings.Repeat("_", emptCount) + "]"
		}
	}

	out := countersBox + barBox + percentBox + speedBox + timeLeftBox
	if len(out) < width {
		end = strings.Repeat(" ", width-len(out))
	}
	fmt.Print("\r" + out + end)
}

type proxyReader struct {
	io.Reader
	bar *ProgressBar
}

func (r *proxyReader) Read(p []byte) (int, error) {
	n, err := r.Reader.Read(p)
	r.bar.Add(n)
	return n, err
}

// NewProxyReader wraps r so that every read advances the bar.
func (p *ProgressBar) NewProxyReader(r io.Reader) io.Reader {
	return &proxyReader{r, p}
}
EOF
