package main

import (
	"fmt"
	"io"
	"net/http"
	"net/url"
	"os"
	"strings"
)

// filenameFromDisposition extracts the filename parameter of a
// Content-Disposition header value.
func filenameFromDisposition(cd string) string {
	filename := ""
	for _, part := range strings.Split(cd, ";") {
		part = strings.TrimSpace(part)
		if !strings.HasPrefix(part, "filename=") {
			continue
		}
		filename = strings.Trim(strings.TrimLeft(part, "filename="), " \"")
	}
	return filename
}

func downloadResponse(r *Request, res *http.Response, u *url.URL) {
	fmt.Println(Color(res.Proto, colorMagenta), Color(res.Status, colorGreen))
	for k, v := range res.Header {
		fmt.Println(Color(k, colorGray), ":", Color(strings.Join(v, " "), colorCyan))
	}
	fmt.Println()

	filename := filenameFromDisposition(res.Header.Get("Content-Disposition"))
	if filename == "" {
		segments := strings.Split(u.Path, "/")
		filename = segments[len(segments)-1]
	}
	fmt.Printf("Downloading to \"%s\"\n", filename)

	fd, err := os.Create(filename)
	if err != nil {
		fatalAt("bat.go:240", "can't create file", err)
	}
	defer fd.Close()

	bar := NewProgressBar(res.ContentLength)
	bar.Start()
	reader := bar.NewProxyReader(res.Body)
	io.Copy(fd, reader)
	bar.Finish()
	res.Body.Close()
}
